  const s={view:'planning',dimension:'calendar',boardProject:'',projectQuery:'',statsScale:'month',statsDate:localDate(new Date()),statsProject:'',statsMetric:'involved',occurrence:'',query:'',data:{},project:'',month:localDate(new Date()).slice(0,7),detail:null,draft:null,draftActive:0,edit:null,followup:'',composer:'',busy:new Set(),detailEpoch:0,error:'',detailTimer:null,preview:null,knowledgeScope:'global',knowledgeQuery:'',knowledge:[],knowledgeScopes:[],detailTab:'overview',operationId:'',operationPayload:'',active:true};
  const e=x=>escape(x==null?'':String(x)), i=x=>icon(x);
