  function unwrap(name,result){return (name==='planning_draft'||name==='planning_intake')&&result&&typeof result==='object'?result.draft:(result&&typeof result==='object'&&Object.prototype.hasOwnProperty.call(result,'item')?result.item:result);}
  function operationId(){return 'intake-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);}
  function saveItem(item){const keys=['intent','target_task_id','expected_version','title','prompt','project_id','project_name','section_id','section_name','start_date','due_date','period','tags','model','effort','sandbox'],out={};for(const key of keys)if(item[key]!==undefined&&item[key]!==''&&item[key]!==null&&item[key]!=='__new__')out[key]=item[key];return out;}
  async function call(name,args){const epoch=name==='planning_detail'?++s.detailEpoch:0;const result=unwrap(name,await tool(name,args||{}));if(name==='planning_detail'&&epoch!==s.detailEpoch)return null;return result||{};}
  function mark(name,on){on?s.busy.add(name):s.busy.delete(name);invalidate();}
