  function projects(selected,all){return '<option value="">'+(all?'全部项目':'选择项目')+'</option>'+list(s.data.projects).map(p=>'<option value="'+e(p.id)+'" '+(p.id===selected?'selected':'')+'>'+e(p.name||p.title||p.id)+'</option>').join('');}
  function sections(project,selected){return '<option value="">不指定分区</option>'+list(s.data.sections).filter(x=>!project||x.project_id===project).map(x=>'<option value="'+e(x.id)+'" '+(x.id===selected?'selected':'')+'>'+e(x.name||x.title||x.id)+'</option>').join('');}
  function projectName(id){const p=list(s.data.projects).find(x=>x.id===id);return p?(p.name||p.title||'已关联'):(id?'已关联':'未指定');}
  function accountName(){return '跟随当前默认账户';}
