  function tasks(){return list(s.data.tasks);}
  function matchesTask(t){const q=s.query.trim().toLocaleLowerCase();return !q||[t.title,projectName(t.project_id)].some(v=>text(v).toLocaleLowerCase().includes(q));}
  function calendarTasks(){return tasks().filter(t=>!s.project||t.project_id===s.project);}
  const dimensions={calendar:'工作计划',projects:'项目跟踪',tasks:'进度统计'};
  function expired(t){const end=text(t?.due_date)||text(t?.start_date);return !!(t?.read_only||(end&&end<localDate(new Date())));}
  function readOnly(){return expired(s.detail)||!!(s.occurrence&&s.occurrence<localDate(new Date()));}
  function requireEditable(){if(readOnly())throw Error('过去日期的工作项仅供查看');}
  function validSchedule(t){if(t.start_date&&t.due_date&&t.due_date<t.start_date)throw Error('截止日期不能早于开始日期');if(expired(t))throw Error('不能将工作项安排到已过去的日期');}
  function dimensionNav(){return '<nav class="subnav planning-dimensions" aria-label="工作台维度">'+Object.entries(dimensions).map(([key,label])=>button('dimension',label,'data-dimension="'+key+'" aria-current="'+(s.dimension===key?'page':'false')+'"')).join('')+'</nav>';}
  const boardStates={pending:['待执行','amber'],running:['执行中','blue'],completed:['已完成','green'],attention:['需处理','rose']};
  function taskColor(id){return [...String(id||'')].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0)%8;}
  function taskColumn(t){if(t.status==='pending'||!t.status)return 'pending';return ['failed','stopped','interrupted'].includes(t.status)?'attention':Object.hasOwn(boardStates,t.status)?t.status:'attention';}
  function taskCounts(ts){return Object.fromEntries(Object.keys(boardStates).map(k=>[k,ts.filter(t=>taskColumn(t)===k).length]));}
