  function statDetails(d){
    const key=s.statsMetric,names={projects:'本期项目',involved:'本期任务',planned:'本期计划',executed:'本期已执行',completed:'本期已完成',running:'当前执行中',pending:'当前未开始',unassigned:'当前未分配','assigned-pending':'当前待执行',attention:'当前需处理'};
    const rows=d.items.filter(t=>key==='projects'||key==='involved'?true:['planned','executed','completed'].includes(key)?d[key].has(t.id):key==='pending'?['pending','unassigned'].includes(taskColumn(t)):key==='assigned-pending'?taskColumn(t)==='pending':taskColumn(t)===key);
    return '<section class="card planning-stat-detail" id="planning-stat-detail"><div class="planning-trend-heading"><h2>'+e(names[key]||'本期任务')+'明细</h2><span class="muted">'+(key==='projects'?d.projectRows.length:rows.length)+' 项</span></div><div class="planning-detail-list">'+(key==='projects'?d.projectRows.map(r=>button('project-board','<span class="planning-task-text"><strong>'+e(r.project.name||r.project.title||r.project.id)+'</strong><small>'+r.tasks.length+' 项本期任务</small></span><span class="badge '+r.status[1]+'">'+r.status[0]+'</span>','class="planning-detail-row" data-project-id="'+e(r.project.id)+'"')).join(''):rows.map(t=>button('detail','<span class="planning-task-text"><strong>'+e(t.title)+'</strong><small>'+e(projectName(t.project_id))+' · '+e([t.start_date,t.due_date].filter(Boolean).join(' 至 ')||'未排期')+'</small></span>'+badge(t.status),'class="planning-detail-row planning-color-'+taskColor(t.id)+'" data-task-id="'+e(t.id)+'"')).join(''))+'</div>'+(!(key==='projects'?d.projectRows.length:rows.length)?'<p class="empty">当前范围暂无对应记录</p>':'')+'</section>';
  }
  function progressStats(){const d=statistics();return metricCards(d)+'<div class="planning-insights-grid">'+trendChart(d)+statusPanel(d)+'</div><div class="planning-insights-bottom">'+projectComparison(d)+statDetails(d)+'</div><details class="planning-stat-data planning-stat-definition"><summary>统计口径</summary><p class="planning-stat-note">本期涉及项目包含：任务排期与本期相交、本期有真实运行或新建任务，以及本期新建的项目。项目状态与任务状态均为当前快照。执行与完成按任务分别去重，跨期开始、本期完成的任务仍计入本期完成。未排期且没有本期活动的任务不计入本期；可在项目跟踪查看全部任务。</p>'+(d.missing?'<p class="planning-stat-note">'+d.missing+' 条运行记录缺少时间，对应的时间指标未计入，完整记录仍可在任务详情查看。</p>':'')+'</details>';}
  function inDay(task,key){const a=text(task.start_date),b=text(task.due_date);if(a&&b)return a<=key&&key<=b;if(a)return a===key;if(b)return b===key;return false;}
  function dayChip(task,key){const first=text(task.start_date)||text(task.due_date),starts=first===key,ends=text(task.due_date)===key,range=[task.start_date,task.due_date].filter(Boolean).join(' 至 ');return '<button type="button" class="planning-calendar-item planning-color-'+taskColor(task.id)+' '+(starts?'starts ':'')+(ends?'ends':'')+'" data-planning-action="detail" data-task-id="'+e(task.id)+'" data-date="'+e(key)+'" title="'+e(task.title+(range?' · '+range:''))+'">'+(starts?e(task.title):'↳ '+e(task.title))+badge(task.status)+'</button>';}
  function monthTitle(){const p=s.month.split('-');return p[0]+' 年 '+Number(p[1])+' 月';}
  function calendar(){const first=new Date(s.month+'-01T00:00:00'),offset=first.getDay(),start=dateStep(first,-offset),today=localDate(new Date()),cells=[];
   for(let n=0;n<42;n++){const d=dateStep(start,n),key=localDate(d),items=calendarTasks().filter(t=>inDay(t,key)),outside=key.slice(0,7)!==s.month,past=key<today,tone=[5,0,1,2,3,4,5][d.getDay()],visible=items.slice(0,3),more=items.slice(3);
    cells.push('<section class="planning-day planning-tone-'+tone+' '+(outside?'outside ':'')+(past?'past ':'')+(key===today?'today':'')+'" aria-label="'+key+(past?'，已过去，仅供查看':'')+'"><header><time datetime="'+key+'"'+(key===today?' aria-current="date"':'')+'>'+d.getDate()+'</time>'+(past?'<span class="planning-day-readonly" title="已过去，仅供查看" aria-label="只读">'+i('lock')+'</span>':button('quick-new',i('plus'),'data-date="'+key+'" aria-label="'+key+' 新增任务"'))+'</header><div class="planning-day-items">'+visible.map(t=>dayChip(t,key)).join('')+(more.length?'<details class="planning-day-more"><summary>另有 '+more.length+' 项</summary>'+more.map(t=>dayChip(t,key)).join('')+'</details>':'')+'</div></section>');}
   return '<section class="planning-month-grid" aria-label="'+e(monthTitle())+'"><div class="planning-weekdays">'+['周日','周一','周二','周三','周四','周五','周六'].map((label,n)=>'<span class="planning-tone-'+[5,0,1,2,3,4,5][n]+'">'+label+'</span>').join('')+'</div><div class="planning-days">'+cells.join('')+'</div></section>';
  }
  function unplanned(){const xs=calendarTasks().filter(t=>!t.start_date&&!t.due_date);return '<aside class="planning-unplanned"><h2>未排期任务 <span class="count">'+xs.length+'</span></h2>'+(xs.map(t=>'<article><div><strong>'+e(t.title)+'</strong><small>'+e(projectName(t.project_id))+'</small></div>'+badge(t.status)+button('detail',i('arrow-right'),'data-task-id="'+e(t.id)+'" aria-label="查看任务"')+'</article>').join('')||'<p class="muted">所有任务均已排期。</p>')+'</aside>';}
  function statsControls(){const p=periodInfo();return '<div class="planning-stat-controls"><div class="planning-period-tabs" role="group" aria-label="统计周期">'+Object.entries({day:'日',month:'月',quarter:'季度',year:'年'}).map(([key,label])=>button('stats-scale',label,'data-scale="'+key+'" aria-pressed="'+(s.statsScale===key)+'"')).join('')+'</div><label>日期 <input type="date" data-planning-stats-date aria-label="选择统计日期" value="'+e(s.statsDate)+'"></label>'+button('stats-prev',i('chevron-left'),'aria-label="上一个周期"')+button('stats-today','本期')+button('stats-next',i('chevron-right'),'aria-label="下一个周期"')+'<strong>'+e(p.title)+'</strong><label class="select">项目 <select data-planning-stats-project aria-label="统计项目">'+projects(s.statsProject,true)+'</select></label></div>';}
  function planning(){
    const isCalendar=s.dimension==='calendar',board=s.dimension==='projects'&&s.boardProject,description={calendar:'查看每日安排与待办任务。',projects:'查看所有项目，进入项目按状态管理任务。',tasks:'查看周期内的项目、任务与执行情况。'}[s.dimension];
    let toolbar='';
    if(isCalendar)toolbar='<div class="toolbar planning-calendar-toolbar"><label class="select">项目 <select data-planning-project aria-label="筛选工作计划项目">'+projects(s.project,true)+'</select></label>'+button('previous-month',i('chevron-left'),'aria-label="上一个月"')+button('today','今天')+button('next-month',i('chevron-right'),'aria-label="下一个月"')+'<strong class="planning-month-label">'+e(monthTitle())+'</strong></div>';
    else if(s.dimension==='tasks')toolbar=statsControls();
    else if(!board)toolbar='<div class="toolbar">'+searchForm()+'</div>';
    const composer=isCalendar?'<form class="planning-composer" data-planning-form="composer"><label for="planning-composer-text">用文字整理工作计划</label><textarea id="planning-composer-text" name="source" placeholder="输入目标、安排或要补充的问题；整理后可逐项修改。">'+e(s.draft?.source||s.composer||'')+'</textarea>'+button('new','整理','data-submit="composer"')+'</form>':'';
    return dimensionNav()+'<div class="planning-page planning-calendar-page">'+(!board?'<div class="heading"><div><h1>'+dimensions[s.dimension]+'</h1><p class="muted">'+description+'</p></div></div>':'')+composer+toolbar+(s.error?'<p class="planning-error" role="alert">'+e(s.error)+'</p>':'')+(isCalendar?'<div class="planning-calendar-layout">'+calendar()+unplanned()+'</div>':s.dimension==='projects'?(board?projectBoard():projectCards()):progressStats())+'</div>';
  }
  function draftRow(item,index){const intent={create_task:'新任务',supplement:'补充说明',question:'问答'}[item.intent]||'新任务',targets='<option value="">选择已有任务</option>'+tasks().map(t=>'<option value="'+e(t.id)+'" '+(t.id===item.target_task_id?'selected':'')+'>'+e(t.title)+'</option>').join(''),newProject=item.project_id==='__new__'||!!item.project_name,newSection=item.section_id==='__new__'||!!item.section_name,projectOptions=projects(newProject?'__new__':(item.project_id||s.project),true)+'<option value="__new__" '+(newProject?'selected':'')+'>新建项目</option>',sectionOptions=sections(newProject?'':(item.project_id||s.project),newSection?'__new__':item.section_id)+'<option value="__new__" '+(newSection?'selected':'')+'>新建分区</option>';return '<fieldset data-draft-item="'+index+'"><legend>'+e(intent)+'</legend><label>类型<select name="intent"><option value="create_task" '+(item.intent==='create_task'?'selected':'')+'>新任务</option><option value="supplement" '+(item.intent==='supplement'?'selected':'')+'>补充说明</option><option value="question" '+(item.intent==='question'?'selected':'')+'>问答</option></select></label><label>标题<input name="title" value="'+e(item.title)+'" required></label><label>内容<textarea name="prompt" required>'+e(item.prompt)+'</textarea></label>'+((item.intent==='supplement'||item.intent==='question')?'<label>追加到任务<select name="target_task_id">'+targets+'</select></label>':'')+'<div class="planning-intake-dates"><label>项目<select name="project_id">'+projectOptions+'</select></label>'+ (newProject?'<label>新项目名称<input name="project_name" value="'+e(item.project_name)+'" required></label>':'') +'<label>分区<select name="section_id">'+sectionOptions+'</select></label>'+(newSection?'<label>新分区名称<input name="section_name" value="'+e(item.section_name)+'" required></label>':'')+'<label>开始日期<input name="start_date" type="date" value="'+e(item.start_date)+'"></label><label>截止日期<input name="due_date" type="date" value="'+e(item.due_date)+'"></label></div><p class="muted">执行时自动使用当前默认账户。</p>'+button('remove-draft-item','移除','data-index="'+index+'"')+'</fieldset>';}
  function draft(){const d=s.draft||{items:[]},items=list(d.items),active=Math.min(s.draftActive||0,Math.max(0,items.length-1)),title=d.mode==='question'?'继续问答':d.mode==='supplement'?'补充说明':'整理工作计划',resultList=items.map((item,n)=>button('draft-select','<strong>'+e(item.title||{create_task:'新任务',supplement:'补充说明',question:'问答'}[item.intent]||'未命名结果')+'</strong><small>'+e({create_task:'新任务',supplement:'补充说明',question:'问答'}[item.intent]||'新任务')+'</small>','class="planning-intake-result '+(n===active?'active':'')+'" data-index="'+n+'"')).join('');return '<section class="planning-dialog-shell" role="dialog" aria-modal="true" aria-label="'+e(title)+'"><div class="planning-dialog"><header><div><p class="muted">文字录入</p><h1>'+e(title)+'</h1></div>'+button('back',i('x')+' 关闭','aria-label="关闭并保留草稿"')+'</header><form data-planning-form="draft" class="planning-form planning-intake-form"><label class="planning-intake-source">说明<textarea name="source" required placeholder="输入目标、安排或要补充的问题">'+e(d.source)+'</textarea></label><div class="planning-intake-submit">'+button('generate','整理','data-submit="generate"')+button('add-draft-item','手动新增')+'</div><section class="planning-intake-workspace"><aside><h2>整理结果</h2>'+ (resultList||'<p class="muted">整理后在此显示结果。</p>')+'</aside><div class="planning-intake-editor">'+(items[active]?draftRow(items[active],active):'<p class="muted">先输入说明并整理，或手动新增一项。</p>')+'</div></section><footer>'+button('save-draft','统一保存','data-submit="save"')+'</footer></form></div></section>';}
  function attachmentRow(asset){const digest=text(asset.sha256);return '<article class="planning-asset" data-asset-id="'+e(asset.id)+'"><div class="planning-file-icon">'+i(safeMime(asset.mime)?'image':'file-text')+'</div><div class="grow"><h3>'+e(asset.name||asset.id)+'</h3><p>'+e(asset.mime||'未知类型')+(asset.version?' · v'+e(asset.version):'')+'</p><small>来源：'+e(asset.source_kind||'资料库')+(asset.run_id?' · 执行：'+e(asset.run_id):'')+(asset.created_at?' · '+e(shownDate(asset.created_at)):'')+'</small>'+(digest?'<small class="planning-digest">SHA-256：'+e(digest)+'</small>':'')+'</div>'+button('preview',i('eye')+' 预览','data-asset-id="'+e(asset.id)+'"')+button('download-asset',i('download')+' 下载','data-asset-id="'+e(asset.id)+'"')+'</article>';}
  function noteStatus(value){return ({not_exported:'尚未导出',created:'已导出',updated:'已更新',unchanged:'无需更新',conflict:'保留手工笔记',failed:'导出失败',unavailable:'暂不可用'})[value]||'尚未导出';}
  function runRow(run){const elapsed=run.elapsed||run.duration||'未知',tokens=run.tokens||run.token_usage||'未知',account=run.execution_account_name||run.execution_account_id||run.account_id||'';return '<article class="planning-run"><strong>'+e(run.state||'unknown')+'</strong><small>'+e(shownDate(run.created_at))+' · 耗时：'+e(elapsed)+' · Token：'+e(tokens)+(account?' · 启动时账户：'+e(account):'')+'</small>'+(run.result?'<p>'+e(run.result)+'</p>':'')+(run.error?'<p class="red">'+e(run.error)+'</p>':'')+(run.thread_id?button('open-native',i('external-link')+' 打开会话','data-thread-id="'+e(run.thread_id)+'"'):'')+'</article>';}
  function messageState(value){return ({saved:'待执行',retryable:'可重试',running:'执行中',completed:'已完成',done:'已完成',review:'待确认',failed:'需处理'})[value]||'待执行';}
  function canRunMessage(message,task){return message.kind==='question'&&['saved','retryable'].includes(message.state||'saved')&&task.status!=='running';}
  function preview(){const p=s.preview||{},image=p.url&&safeMime(p.mime)?'<img src="'+e(p.url)+'" alt="'+e(p.name)+'">':'';return '<section class="planning-preview" role="dialog" aria-modal="true" aria-label="资料预览"><div class="planning-preview-head"><h2>'+e(p.name)+'</h2>'+button('close-preview',i('x'),'aria-label="关闭预览"')+'</div>'+(image||'<p class="muted">该文件不支持在工作台内预览。</p>')+'<footer>'+(p.url?'<a class="planning-download" href="'+e(p.url)+'" download="'+e(p.name)+'">'+i('download')+' 下载</a>':'')+'</footer></section>';}
  function detail(){const readonly=readOnly(),t=s.detail||{},runs=list(t.runs),assets=list(t.assets||t.library_assets),refs=list(t.knowledge_refs),messages=list(t.messages),tab=s.detailTab||'overview',tabs=[['overview','概览'],['messages','对话'],['runs','运行'],['files','关联文件']],nav='<nav class="planning-detail-tabs" aria-label="任务详情">'+tabs.map(([id,label])=>button('detail-tab',label,'data-tab="'+id+'" aria-current="'+(tab===id?'page':'false')+'"')).join('')+'</nav>';let content='';if(tab==='overview')content='<section class="planning-detail-main"><h2>执行说明</h2><p class="planning-pre">'+e(t.prompt||'暂无')+'</p><dl><dt>项目</dt><dd>'+e(projectName(t.project_id))+'</dd><dt>执行账户</dt><dd>'+e(accountName(t.execution_account_id))+'</dd><dt>Obsidian</dt><dd>'+e(noteStatus(t.note_status))+'</dd></dl></section>';else if(tab==='messages')content='<section class="planning-detail-list">'+(messages.map(m=>'<article class="planning-message"><strong>'+e(m.kind==='question'?'问答':m.kind==='supplement'?'补充说明':'记录')+'</strong><small>'+e(shownDate(m.created_at))+' · '+e(messageState(m.state))+'</small><p>'+e(m.content||m.prompt||'')+'</p>'+(m.result?'<p>'+e(m.result)+'</p>':'')+(list(m.runs).map(runRow).join(''))+(m.kind==='question'&&!m.result&&!list(m.runs).length?'<p class="muted">执行时间与 Token 用量：未知</p>':'')+(canRunMessage(m,t)&&!readonly?button('start','执行问答','data-task-id="'+e(t.id)+'" data-message-id="'+e(m.id||m.message_id)+'"'):'')+'</article>').join('')||'<p class="muted">暂无对话记录</p>')+'</section>';else if(tab==='runs')content='<section class="planning-detail-list">'+(runs.map(runRow).join('')||'<p class="muted">尚未执行</p>')+'</section>';else content='<section class="planning-detail-list">'+(readonly?'':'<input id="planning-file-input" type="file" multiple hidden>'+button('pick-upload','上传附件'))+(assets.map(attachmentRow).join('')||'<p class="muted">暂无关联资料</p>')+(refs.map(k=>'<article><strong>'+e(k.title||k.key)+'</strong><small>'+e(k.scope)+' · '+e(k.linked_at?shownDate(k.linked_at):'')+'</small></article>').join(''))+(readonly?'':button('knowledge','关联知识','data-task-id="'+e(t.id)+'"'))+'</section>';return '<section class="planning-dialog-shell planning-detail-dialog" role="dialog" aria-modal="true" aria-label="任务详情"><div class="planning-dialog"><header><div><p class="muted">任务详情</p><h1>'+e(t.title||'工作项')+'</h1><p>'+badge(t.status)+'</p></div>'+button('back',i('x')+' 关闭','aria-label="关闭任务详情"')+'</header>'+(readonly?'<p class="planning-readonly-notice" role="status">'+i('lock')+' '+(s.occurrence&&s.occurrence<localDate(new Date())?'正在查看 '+e(s.occurrence)+' 的历史安排，仅供查看。':'该工作项的排期已过去，仅供查看。')+'</p>':'')+nav+content+'<footer class="planning-actions">'+(readonly?'':(t.status==='running'?button('stop','停止执行','data-task-id="'+e(t.id)+'"'):button('start','执行任务','data-task-id="'+e(t.id)+'"'))+button('edit','编辑','data-task-id="'+e(t.id)+'"')+button('new-supplement','补充说明','data-task-id="'+e(t.id)+'"')+button('new-question','继续问答','data-task-id="'+e(t.id)+'"')+button('export','导出 Obsidian','data-task-id="'+e(t.id)+'"')+button('archive','归档输出','data-task-id="'+e(t.id)+'"')+button('delete','删除任务（保留资料）','data-task-id="'+e(t.id)+'"'))+(t.native_thread_id?button('open-native',i('external-link')+' 打开会话','data-thread-id="'+e(t.native_thread_id)+'"'):'')+'</footer>'+(s.preview?preview():'')+'</div></section>';}
  function edit(){const t={...(s.detail||{}),...(s.edit||{})};return '<section class="planning-dialog-shell" role="dialog" aria-modal="true" aria-label="编辑任务"><div class="planning-dialog"><div class="planning-page"><div class="heading"><h1>编辑任务</h1>'+button('detail',i('arrow-left')+' 返回详情','data-task-id="'+e(t.id)+'"')+'</div><form data-planning-form="edit" class="planning-form"><label>标题<input name="title" value="'+e(t.title)+'" required></label><label>说明<textarea name="prompt">'+e(t.prompt)+'</textarea></label><label>开始日期<input name="start_date" type="date" value="'+e(t.start_date)+'"></label><label>截止日期<input name="due_date" type="date" value="'+e(t.due_date)+'"></label><p class="muted">执行时自动使用当前默认账户。</p>'+button('save-edit','保存修改','data-submit="edit"')+'</form></div></div></section>';}
  function knowledge(){const scopes=s.knowledgeScopes.length?s.knowledgeScopes:list(s.data.scopes),scope=s.knowledgeScope||s.data.selected_scope||'global';return '<section class="planning-dialog-shell" role="dialog" aria-modal="true" aria-label="关联已审核知识"><div class="planning-dialog"><div class="planning-page"><div class="heading"><h1>关联已审核知识</h1>'+button('detail',i('arrow-left')+' 返回工作项','data-task-id="'+e((s.detail||{}).id)+'"')+'</div><div class="toolbar"><label class="select"><select data-planning-knowledge-scope><option value="global" '+(scope==='global'?'selected':'')+'>全局知识</option>'+scopes.filter(x=>x.id!=='global').map(x=>'<option value="'+e(x.id)+'" '+(scope===x.id?'selected':'')+'>'+e(x.name||x.title||x.id)+'</option>').join('')+'</select></label><label class="search"><input data-planning-knowledge-query value="'+e(s.knowledgeQuery)+'" placeholder="搜索已审核知识"></label>'+button('search-knowledge','搜索')+'</div><section class="planning-knowledge-list">'+(list(s.knowledge).map(k=>'<article class="planning-knowledge"><div><h2>'+e(k.title||k.knowledge_key)+'</h2><p>'+e(k.summary||k.scope_key||'')+'</p></div>'+button('link-knowledge','关联','data-scope="'+e(k.scope_key||scope)+'" data-key="'+e(k.knowledge_key)+'"')+'</article>').join('')||'<p class="empty">输入范围或关键词后搜索已审核知识。</p>')+'</section></div></div></section>';}
  function render(view,data){const internal=['draft','detail','edit','knowledge'].includes(s.view),requested=view||s.view;if(!(internal&&requested==='planning'))s.view=requested==='library'?'planning':requested;s.data=data||s.data||{};if(['edit','knowledge'].includes(s.view)&&readOnly()){s.edit=null;s.view='detail';}const background='<div class="planning-modal-background" aria-hidden="true" inert>'+planning()+'</div>';if(s.view==='draft')return background+draft();if(s.view==='detail')return background+detail();if(s.view==='edit')return background+edit();if(s.view==='knowledge')return background+knowledge();return planning();}
  function values(form){const out={};if(!form)return out;for(const node of Array.from(form.querySelectorAll?.('input,textarea,select')||[]))if(node.name)out[node.name]=node.value;return out;}
  function capture(root){const composer=root&&root.querySelector('[data-planning-form="composer"]');if(composer)s.composer=values(composer).source||s.composer;const df=root&&root.querySelector('[data-planning-form="draft"]');if(df){const v=values(df),rows=Array.from(df.querySelectorAll?.('[data-draft-item]')||[]).filter(Boolean),rowValues=Object.fromEntries(rows.filter(row=>row.dataset).map(row=>[row.dataset.draftItem,values(row)])),items=list(s.draft?.items).map((item,n)=>{const change=rowValues[n]||{},target=tasks().find(t=>t.id===(change.target_task_id||item.target_task_id)),targetChanged=change.target_task_id!==undefined&&change.target_task_id!==item.target_task_id,expected=target&&(!item.expected_version||targetChanged)?target.version:item.expected_version;return {...item,...change,...(expected===undefined||expected===null?{}:{expected_version:expected})};});const payload=JSON.stringify(items);if(payload!==s.operationPayload)s.operationId='';s.draft={...(s.draft||{}),...v,items};}const ef=root&&root.querySelector('[data-planning-form="edit"]');if(ef)s.edit={...(s.edit||{}),...values(ef)};const ff=root&&root.querySelector('[data-planning-form="followup"]');if(ff)s.followup=values(ff).prompt||'';}
  function clearPreview(){if(s.preview?.url)URL.revokeObjectURL(s.preview.url);s.preview=null;}
  function stopDetailPoll(){clearTimeout(s.detailTimer);s.detailTimer=null;}
  function startDetailPoll(){stopDetailPoll();if(!s.active||s.view!=='detail'||!s.detail||s.detail.status!=='running')return;s.detailTimer=setTimeout(async()=>{try{if(globalThis.document?.hidden||s.view!=='detail'||s.edit)return;const item=await call('planning_detail',{task_id:s.detail.id});if(item&&s.view==='detail'&&!s.edit){s.detail=item;invalidate();startDetailPoll();}}catch(_){startDetailPoll();}},3000);}
  async function detailLoad(id,occurrence=''){mark('detail',true);try{const item=await call('planning_detail',{task_id:id});if(!item)return;if(s.detail?.id!==id){s.followup='';clearPreview();}s.detail=item;s.occurrence=occurrence;s.edit=null;s.view='detail';startDetailPoll();}finally{mark('detail',false);}}
  const base64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('读取文件失败'));reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.readAsDataURL(file);});
  async function upload(files){requireEditable();const taskId=['detail','edit'].includes(s.view)&&s.detail?s.detail.id:null;for(const file of Array.from(files||[])){if(!file||file.size>33554432)throw Error('文件需小于 32 MiB');if(file.size<=262144)await call('library_upload',{name:file.name,mime:file.type||null,content_base64:await base64(file),task_id:taskId});else{const begun=await call('library_upload_begin',{name:file.name,mime:file.type||null,size:file.size,task_id:taskId});let offset=0;while(offset<file.size){const chunk=file.slice(offset,offset+262144);await call('library_upload_chunk',{upload_id:begun.upload_id,offset,content_base64:await base64(chunk)});offset+=chunk.size;}await call('library_upload_commit',{upload_id:begun.upload_id});}}if(taskId){const item=await call('planning_detail',{task_id:taskId});if(item&&s.active&&s.view==='detail'&&s.detail?.id===taskId){s.detail=item;invalidate();}}}
  async function assetUrl(id){let offset=0,parts=[],meta={};for(;;){const item=await call('library_content',{asset_id:id,offset,length:262144});if(!item)break;meta=item;parts.push(item.content_base64||'');if(item.complete)break;offset=item.next_offset;}const bytes=parts.map(part=>Uint8Array.from(atob(part),c=>c.charCodeAt(0)));return {url:URL.createObjectURL(new Blob(bytes,{type:meta.mime||'application/octet-stream'})),name:meta.name||id,mime:meta.mime||''};}
  async function dispatch(name,el,root){if(s.busy.has(name))return;const id=el.dataset?.taskId;try{
   if(['edit','save-edit','start','stop','archive','export','delete','knowledge','link-knowledge','followup','pick-upload'].includes(name))requireEditable();
   if(name==='search'){const input=root.querySelector('[data-planning-query]');s.query=input?input.value:s.query;} else if(name==='clear-project'){s.project='';} else if(name==='dimension'){if(Object.hasOwn(dimensions,el.dataset.dimension)){s.dimension=el.dataset.dimension;s.query='';s.boardProject='';}} else if(name==='project-board'){s.projectQuery=s.query;s.boardProject=el.dataset.projectId;s.query='';s.dimension='projects';} else if(name==='projects-back'){s.boardProject='';s.query=s.projectQuery;s.projectQuery='';} else if(name==='stats-scale'){if(['day','month','quarter','year'].includes(el.dataset.scale)){s.statsScale=el.dataset.scale;s.statsMetric='involved';}} else if(name==='stats-prev')periodShift(-1); else if(name==='stats-next')periodShift(1); else if(name==='stats-today')s.statsDate=localDate(new Date()); else if(name==='stat-metric')s.statsMetric=el.dataset.metric; else if(name==='previous-month')s.month=monthStep(s.month,-1); else if(name==='next-month')s.month=monthStep(s.month,1); else if(name==='today')s.month=localDate(new Date()).slice(0,7);
   else if(name==='new'){if(!s.draft){s.draft={items:[],project_id:s.project||'',source:s.composer||'',mode:'create_task'};s.operationId='';s.operationPayload='';s.draftActive=0;}s.view='draft';} else if(name==='quick-new'){const d=el.dataset.date;if(d<localDate(new Date()))throw Error('过去日期仅供查看');s.draft={items:[{intent:'create_task',title:'',prompt:'',start_date:d,due_date:d,project_id:s.project||''}],project_id:s.project||'',source:s.composer||'',mode:'create_task'};s.operationId='';s.operationPayload='';s.draftActive=0;s.view='draft';}
   else if(name==='back'){s.detailEpoch++;stopDetailPoll();s.edit=null;clearPreview();s.view='planning';s.error='';await refresh({refresh:false});setTimeout(()=>root?.querySelector?.('[data-planning-form="composer"] textarea')?.focus?.(),0);} else if(name==='detail')await detailLoad(id,el.dataset.date||''); else if(name==='detail-tab'){s.detailTab=el.dataset.tab||'overview';} else if(name==='new-supplement'||name==='new-question'){s.draft={items:[{intent:name==='new-question'?'question':'supplement',target_task_id:s.detail.id,expected_version:s.detail.version,title:s.detail.title,prompt:'',project_id:s.detail.project_id||''}],task_id:s.detail.id,project_id:s.detail.project_id||'',source:'',mode:name==='new-question'?'question':'supplement'};s.draftActive=0;s.operationId='';s.view='draft';} else if(name==='edit'){stopDetailPoll();s.edit={...s.detail};s.view='edit';} else if(name==='draft-select'){s.draftActive=Number(el.dataset.index)||0;} else if(name==='add-draft-item'){s.draft=s.draft||{items:[]};s.draft.items.push({intent:'create_task',title:'',prompt:'',start_date:'',due_date:'',project_id:s.draft.project_id||s.project||''});s.draftActive=s.draft.items.length-1;s.operationId='';} else if(name==='remove-draft-item'){s.draft.items.splice(Number(el.dataset.index),1);s.draftActive=Math.max(0,s.draftActive-1);s.operationId='';}
   else if(name==='generate'){capture(root);const d=s.draft||{},v={text:d.source,project_id:d.project_id||null,task_id:d.task_id||null,start_date:d.start_date||null,due_date:d.due_date||null,period:d.period||null};if(!text(v.text).trim())throw Error('请先输入说明');mark(name,true);const result=await call('planning_intake',v);s.draft={...d,...result,source:d.source,project_id:d.project_id||s.project||'',items:list(result.items)};s.operationId='';s.operationPayload='';}
   else if(name==='save-draft'){capture(root);const d=s.draft||{},items=list(d.items).map(saveItem);if(!items.length)throw Error('至少保留一项结果');for(const item of items)validSchedule(item);const payload=JSON.stringify(items);if(payload!==s.operationPayload){s.operationId=operationId();s.operationPayload=payload;}mark(name,true);const result=await call('planning_intake_save',{operation_id:s.operationId,items});s.draft=null;s.operationId='';s.operationPayload='';s.view='planning';await refresh({refresh:true});notify(list(result.items).length?'已保存，尚未执行':'已保存');}
   else if(name==='save-edit'){capture(root);const v=s.edit||{};validSchedule(v);mark(name,true);s.detail=await call('planning_update',{task_id:s.detail.id,expected_version:s.detail.version,patch:{title:v.title,prompt:v.prompt,start_date:v.start_date||null,due_date:v.due_date||null}});s.edit=null;s.view='detail';startDetailPoll();}
   else if(name==='start'){mark(name,true);await call('planning_start',{task_id:id,expected_version:s.detail.version,message_id:el.dataset.messageId||null});await detailLoad(id);} else if(name==='stop'){mark(name,true);await call('planning_stop',{task_id:id,expected_version:s.detail.version});await detailLoad(id);}
   else if(name==='archive'){mark(name,true);s.detail=await call('planning_archive',{task_id:id});notify('已归档可用输出');}
   else if(name==='export'){mark(name,true);const result=await call('planning_export',{task_id:id});if(result.status==='conflict'||list(result.conflicts).length)notify('保留手工笔记，部分内容未同步',true);else notify('已导出 Obsidian 笔记');s.detail=await call('planning_detail',{task_id:id});}
   else if(name==='knowledge'){stopDetailPoll();s.view='knowledge';s.knowledge=[];mark(name,true);const result=await call('knowledge_list',{scope:s.knowledgeScope||'global',query:s.knowledgeQuery});s.knowledge=list(result.knowledge);s.knowledgeScopes=list(result.scopes);}
   else if(name==='search-knowledge'){const query=root.querySelector?.('[data-planning-knowledge-query]');s.knowledgeQuery=query?query.value:s.knowledgeQuery;mark(name,true);const result=await call('knowledge_list',{scope:s.knowledgeScope||s.data.selected_scope||'global',query:s.knowledgeQuery});s.knowledge=list(result.knowledge);s.knowledgeScopes=list(result.scopes);}
   else if(name==='link-knowledge'){mark(name,true);s.detail=await call('planning_knowledge_link',{task_id:s.detail.id,scope:el.dataset.scope,key:el.dataset.key});s.view='detail';notify('知识已显式关联');}
   else if(name==='open-native'){try{await openNative('codex://threads/'+encodeURIComponent(el.dataset.threadId));}catch(error){fail(error);}}
   else if(name==='preview'){mark(name,true);const item=await assetUrl(el.dataset.assetId);if(s.preview?.url)URL.revokeObjectURL(s.preview.url);s.preview=item;}
   else if(name==='close-preview'){if(s.preview?.url)URL.revokeObjectURL(s.preview.url);s.preview=null;}
   else if(name==='download-asset'){mark(name,true);const item=await assetUrl(el.dataset.assetId);const a=document.createElement?.('a');if(a){a.href=item.url;a.download=item.name;a.click();}setTimeout(()=>URL.revokeObjectURL(item.url),1000);}
   else if(name==='delete'){if(!window.confirm('删除工作项会保留附件和记录，确定继续吗？'))return;mark(name,true);await call('planning_delete',{task_id:id,expected_version:s.detail.version});s.detail=null;s.view='planning';await refresh({refresh:true});}
   else if(name==='followup'){capture(root);mark(name,true);s.detail=await call('planning_followup',{task_id:s.detail.id,expected_version:s.detail.version,prompt:s.followup});notify('追问已保存，未执行');} else if(name==='pick-upload')root.querySelector('#planning-file-input').click();
  }catch(error){fail(error);}finally{mark(name,false);invalidate();}}
  function bind(root){if(!root)return;s.active=true;globalThis.document?.removeEventListener?.('visibilitychange',visibility);globalThis.document?.addEventListener?.('visibilitychange',visibility);if(s.boundRoot&&s.handlers)for(const [type,fn] of s.handlers)s.boundRoot.removeEventListener?.(type,fn);
   const click=ev=>{const el=ev.target.closest?.('[data-planning-action]');if(el){ev.preventDefault();capture(root);dispatch(el.dataset.planningAction,el,root);}};
   const change=ev=>{const node=ev.target;capture(root);if(s.view==='draft'&&['project_id','section_id'].includes(node.name)){if(node.name==='project_id')s.draft.section_id='';invalidate();}if(node.matches?.('[data-planning-project]')){s.project=node.value;s.query='';invalidate();}if(node.matches?.('[data-planning-stats-project]')){s.statsProject=node.value;invalidate();}if(node.matches?.('[data-planning-stats-date]')){if(/^\d{4}-\d{2}-\d{2}$/.test(node.value)&&stamp(node.value+'T00:00:00'))s.statsDate=node.value;invalidate();}if(node.matches?.('[data-planning-knowledge-scope]')){s.knowledgeScope=node.value||'global';s.knowledge=[];invalidate();}if(node.id==='planning-file-input')upload([...node.files]).catch(fail);};
   const input=ev=>{capture(root);if(ev.target.matches?.('[data-planning-query]'))s.query=ev.target.value;if(ev.target.matches?.('[data-planning-knowledge-query]'))s.knowledgeQuery=ev.target.value;};
   const submit=ev=>{if(ev.target.matches?.('[data-planning-search-form]')){ev.preventDefault();dispatch('search',{},root);return;}if(!ev.target.matches?.('[data-planning-form]'))return;ev.preventDefault();capture(root);if(ev.target.matches?.('[data-planning-form="composer"]')){dispatch('new',ev.submitter||{},root);return;}const a=ev.submitter?.dataset?.submit;dispatch(a==='generate'?'generate':a==='save'?'save-draft':a==='edit'?'save-edit':'followup',ev.submitter||{},root);};
   const keydown=ev=>{if(ev.key==='Escape'&&['draft','detail','edit','knowledge'].includes(s.view)){ev.preventDefault();capture(root);dispatch('back',{},root);}};
   s.boundRoot=root;s.handlers=[['click',click],['change',change],['input',input],['submit',submit],['keydown',keydown]];for(const [type,fn] of s.handlers)root.addEventListener(type,fn);
  }
  const visibility=()=>{if(globalThis.document?.hidden)stopDetailPoll();else if(s.view==='detail')startDetailPoll();};
  globalThis.document?.addEventListener?.('visibilitychange',visibility);
  function leave(){s.active=false;s.detailEpoch++;stopDetailPoll();if(s.preview?.url)URL.revokeObjectURL(s.preview.url);s.preview=null;globalThis.document?.removeEventListener?.('visibilitychange',visibility);s.busy.clear();if(s.boundRoot&&s.handlers)for(const [type,fn] of s.handlers)s.boundRoot.removeEventListener?.(type,fn);s.boundRoot=null;s.handlers=null;}
  async function openTask(id){if(!id)return;await detailLoad(id);return s.detail;}
  function home(){s.detailEpoch++;stopDetailPoll();s.view='planning';s.dimension='calendar';s.query='';s.boardProject='';s.edit=null;s.occurrence='';s.error='';clearPreview();}
  return {render,bind,leave,openTask,home,state:s};
